#!/usr/bin/env tsx
/**
 * YOLO v203 Cross-Runtime Parity Verifier (Python vs Node.js)
 *
 * Reads independent ground-truth reference generated by Python ONNX Runtime
 * from `fixtures/reference/yolo-v203-python-reference.json`, validates hashes and
 * configs, runs local Node.js ONNX inference on the same fixtures, and performs
 * geometric bipartite matching with maximum cardinality and minimum L1 distance.
 *
 * Distinct error statuses:
 *   - PARITY_PASSED
 *   - BLOCKED_MISSING_PYTHON_REFERENCE
 *   - REFERENCE_HASH_MISMATCH
 *   - REFERENCE_CONFIG_MISMATCH
 *   - PARITY_MISMATCH
 */

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import * as ort from 'onnxruntime-node';
import {
  preprocessForYolo,
} from '../lib/detection/yolo/yolo-preprocessing';
import {
  YOLO_V203_INPUT_SIZE,
} from '../lib/detection/yolo/yolo-class-map-v203';
import {
  decodeAndFilterV203,
  type YoloV203Detection,
} from '../lib/detection/yolo/yolo-decoder-v203';
import {
  getYoloV203Session,
  DEFAULT_V203_MODEL_PATH,
} from '../lib/detection/yolo/yolo-inference-v203';

export const DEFAULT_REFERENCE_PATH = path.resolve(
  process.cwd(),
  'fixtures/reference/yolo-v203-python-reference.json',
);

/** Geometric gating distance threshold (pixels) */
export const GEOMETRIC_GATE_MAX_DISTANCE = 50.0;

export function computeFileSha256(filePath: string): string {
  const buf = fs.readFileSync(filePath);
  return crypto.createHash('sha256').update(buf).digest('hex');
}

export function computeIoU(
  boxA: [number, number, number, number],
  boxB: [number, number, number, number],
): number {
  const x1 = Math.max(boxA[0], boxB[0]);
  const y1 = Math.max(boxA[1], boxB[1]);
  const x2 = Math.min(boxA[2], boxB[2]);
  const y2 = Math.min(boxA[3], boxB[3]);

  const intersection = Math.max(0, x2 - x1) * Math.max(0, y2 - y1);
  const areaA = Math.max(0, boxA[2] - boxA[0]) * Math.max(0, boxA[3] - boxA[1]);
  const areaB = Math.max(0, boxB[2] - boxB[0]) * Math.max(0, boxB[3] - boxB[1]);
  const union = areaA + areaB - intersection;

  return union > 0 ? intersection / union : 0;
}

export function computeL1Distance(
  boxA: [number, number, number, number],
  boxB: [number, number, number, number],
): number {
  return (
    Math.abs(boxA[0] - boxB[0]) +
    Math.abs(boxA[1] - boxB[1]) +
    Math.abs(boxA[2] - boxB[2]) +
    Math.abs(boxA[3] - boxB[3])
  );
}

export interface PythonReferenceDetection {
  rawClassId: number;
  score: number;
  bbox: [number, number, number, number]; // [x1, y1, x2, y2]
}

export interface PythonFixtureReference {
  filename: string;
  dimensions: [number, number];
  sha256: string;
  letterbox: {
    scale: number;
    scaledWidth: number;
    scaledHeight: number;
    padX: number;
    padY: number;
    bottomPad: number;
    rightPad: number;
  };
  detections: PythonReferenceDetection[];
  sourceCrop?: {
    sourceFile: string;
    sourceDimensions: [number, number];
    sourceSha256: string;
    cropBox: [number, number, number, number];
  };
}

export interface PythonReferenceFile {
  metadata: {
    generatedAt: string;
    environment: {
      pythonVersion: string;
      onnxruntimeVersion: string;
      numpyVersion: string;
      opencvVersion: string;
      executionProvider: string;
      platform: string;
    };
    model: {
      filename: string;
      sha256: string;
    };
    config: {
      imgsz: number;
      rect: boolean;
      confidenceThreshold: number;
      nmsIouThreshold: number;
      maxDetections: number;
      classAware: boolean;
      labelAssignment: string;
      dtype: string;
    };
  };
  fixtures: Record<string, PythonFixtureReference>;
}

export interface ParityComparisonRow {
  fixture: string;
  rawClassId: number;
  pyConfidence: number | null;
  nodeConfidence: number | null;
  confDelta: number | null;
  pyBbox: [number, number, number, number] | null;
  nodeBbox: [number, number, number, number] | null;
  maxBboxDelta: number | null;
  l1Distance: number | null;
  iou: number | null;
  matched: boolean;
  status: 'MATCH' | 'MISMATCH' | 'MISSING' | 'EXTRA';
}

export interface ParityReport {
  statusCode:
    | 'PARITY_PASSED'
    | 'BLOCKED_MISSING_PYTHON_REFERENCE'
    | 'REFERENCE_HASH_MISMATCH'
    | 'REFERENCE_CONFIG_MISMATCH'
    | 'PARITY_MISMATCH';
  referenceMetadata?: PythonReferenceFile['metadata'];
  model: {
    path: string;
    diskSha256: string;
    referenceSha256?: string;
  };
  fixtures: Record<
    string,
    {
      path: string;
      dimensions: [number, number];
      diskSha256: string;
      referenceSha256?: string;
    }
  >;
  config: {
    confidenceThreshold: number;
    nmsIouThreshold: number;
    maxDetections: number;
  };
  comparisons: ParityComparisonRow[];
  summary: {
    totalPythonDetections: number;
    totalNodeDetections: number;
    matchedCount: number;
    missingCount: number;
    extraCount: number;
    maxConfDelta: number;
    maxBboxDelta: number;
    passed: boolean;
  };
}

/**
 * Solve Maximum-Cardinality Minimum-L1-Cost Bipartite Matching for one class.
 * Ensures that candidates are only matched if they pass the geometric gate
 * (IoU > 0 or L1 distance <= GEOMETRIC_GATE_MAX_DISTANCE).
 */
export function solveGeometricBipartiteMatching(
  pyItems: Array<{ index: number; score: number; bbox: [number, number, number, number] }>,
  nodeItems: Array<{ index: number; score: number; bbox: [number, number, number, number] }>,
  gateMaxDistance = GEOMETRIC_GATE_MAX_DISTANCE,
): {
  matchedPairs: Array<{
    pyIndex: number;
    nodeIndex: number;
    l1Distance: number;
    iou: number;
  }>;
  unmatchedPyIndices: number[];
  unmatchedNodeIndices: number[];
} {
  const pCount = pyItems.length;
  const nCount = nodeItems.length;

  if (pCount === 0 || nCount === 0) {
    return {
      matchedPairs: [],
      unmatchedPyIndices: pyItems.map((p) => p.index),
      unmatchedNodeIndices: nodeItems.map((n) => n.index),
    };
  }

  // Cost matrix: cost[p][n] = finite cost if valid edge, Infinity if forbidden
  const costMatrix: number[][] = [];
  const iouMatrix: number[][] = [];
  const distMatrix: number[][] = [];

  for (let p = 0; p < pCount; p++) {
    costMatrix[p] = [];
    iouMatrix[p] = [];
    distMatrix[p] = [];

    for (let n = 0; n < nCount; n++) {
      const iou = computeIoU(pyItems[p].bbox, nodeItems[n].bbox);
      const dist = computeL1Distance(pyItems[p].bbox, nodeItems[n].bbox);

      iouMatrix[p][n] = iou;
      distMatrix[p][n] = dist;

      // Geometric gate: must have either IoU > 0 or L1 dist <= gateMaxDistance
      if (iou > 0 || dist <= gateMaxDistance) {
        costMatrix[p][n] = dist;
      } else {
        costMatrix[p][n] = Infinity;
      }
    }
  }

  // Find all valid assignment pairs with max cardinality and minimum total distance
  // Deterministic Branch & Bound search (pCount, nCount are small in P&ID detection)
  let bestMatching: Array<[number, number]> = [];
  let bestTotalDist = Infinity;

  function search(pIdx: number, usedNodes: Set<number>, currentPairs: Array<[number, number]>, currentDist: number) {
    if (pIdx >= pCount) {
      if (
        currentPairs.length > bestMatching.length ||
        (currentPairs.length === bestMatching.length && currentDist < bestTotalDist)
      ) {
        bestMatching = [...currentPairs];
        bestTotalDist = currentDist;
      }
      return;
    }

    // Option 1: Try matching pyItems[pIdx] to an available nodeItem
    const validCandidates: Array<{ nIdx: number; cost: number }> = [];
    for (let n = 0; n < nCount; n++) {
      if (!usedNodes.has(n) && Number.isFinite(costMatrix[pIdx][n])) {
        validCandidates.push({ nIdx: n, cost: costMatrix[pIdx][n] });
      }
    }

    // Sort candidate nodes by cost ascending, then by nIdx ascending for deterministic tie-break
    validCandidates.sort((a, b) => a.cost - b.cost || a.nIdx - b.nIdx);

    for (const cand of validCandidates) {
      usedNodes.add(cand.nIdx);
      currentPairs.push([pIdx, cand.nIdx]);
      search(pIdx + 1, usedNodes, currentPairs, currentDist + cand.cost);
      currentPairs.pop();
      usedNodes.delete(cand.nIdx);
    }

    // Option 2: Skip matching pyItems[pIdx] (remains unmatched)
    search(pIdx + 1, usedNodes, currentPairs, currentDist);
  }

  search(0, new Set(), [], 0);

  const matchedPySet = new Set<number>();
  const matchedNodeSet = new Set<number>();
  const matchedPairs: Array<{ pyIndex: number; nodeIndex: number; l1Distance: number; iou: number }> = [];

  for (const [pIdx, nIdx] of bestMatching) {
    matchedPySet.add(pyItems[pIdx].index);
    matchedNodeSet.add(nodeItems[nIdx].index);
    matchedPairs.push({
      pyIndex: pyItems[pIdx].index,
      nodeIndex: nodeItems[nIdx].index,
      l1Distance: distMatrix[pIdx][nIdx],
      iou: iouMatrix[pIdx][nIdx],
    });
  }

  const unmatchedPyIndices = pyItems.filter((p) => !matchedPySet.has(p.index)).map((p) => p.index);
  const unmatchedNodeIndices = nodeItems.filter((n) => !matchedNodeSet.has(n.index)).map((n) => n.index);

  return {
    matchedPairs,
    unmatchedPyIndices,
    unmatchedNodeIndices,
  };
}

export async function runParityVerification(
  referencePath = DEFAULT_REFERENCE_PATH,
  modelPath = DEFAULT_V203_MODEL_PATH,
): Promise<ParityReport> {
  // 1. Check if external reference JSON exists (Fail-closed)
  if (!fs.existsSync(referencePath)) {
    const err = new Error(
      `BLOCKED_MISSING_PYTHON_REFERENCE: Reference file not found at ${referencePath}. ` +
      `Please run 'python scripts/python/generate_reference_v203.py' to generate it.`,
    );
    (err as any).statusCode = 'BLOCKED_MISSING_PYTHON_REFERENCE';
    throw err;
  }

  let refData: PythonReferenceFile;
  try {
    const rawJson = fs.readFileSync(referencePath, 'utf8');
    refData = JSON.parse(rawJson) as PythonReferenceFile;
  } catch (err: any) {
    const parseErr = new Error(`BLOCKED_MISSING_PYTHON_REFERENCE: Invalid reference JSON at ${referencePath}: ${err.message}`);
    (parseErr as any).statusCode = 'BLOCKED_MISSING_PYTHON_REFERENCE';
    throw parseErr;
  }

  // 2. Compute disk file hashes
  if (!fs.existsSync(modelPath)) {
    throw new Error(`Model file not found at: ${modelPath}`);
  }
  const modelDiskSha = computeFileSha256(modelPath);

  // Validate Model SHA-256 against reference
  if (refData.metadata.model.sha256 !== modelDiskSha) {
    const err = new Error(
      `REFERENCE_HASH_MISMATCH: Model SHA mismatch. Disk=${modelDiskSha}, Reference=${refData.metadata.model.sha256}`,
    );
    (err as any).statusCode = 'REFERENCE_HASH_MISMATCH';
    throw err;
  }

  // 3. Validate Configuration
  const expectedConf = 0.50;
  const expectedIou = 0.70;
  const expectedMaxDet = 300;
  const expectedImgsz = 1024;

  const refConf = refData.metadata.config;
  if (
    refConf.confidenceThreshold !== expectedConf ||
    refConf.nmsIouThreshold !== expectedIou ||
    refConf.maxDetections !== expectedMaxDet ||
    refConf.imgsz !== expectedImgsz ||
    !refConf.classAware
  ) {
    const err = new Error(
      `REFERENCE_CONFIG_MISMATCH: Configuration mismatch in reference file. ` +
      `Expected conf=${expectedConf}, iou=${expectedIou}, maxDet=${expectedMaxDet}, imgsz=${expectedImgsz}`,
    );
    (err as any).statusCode = 'REFERENCE_CONFIG_MISMATCH';
    throw err;
  }

  // 4. Validate Fixtures on Disk and verify SHAs
  const fixturePaths: Record<string, string> = {
    square: path.resolve(process.cwd(), 'fixtures/Sheet_1-1__x0_y0.png'),
    nonSquareOddPadding: path.resolve(process.cwd(), 'fixtures/Sheet_1-1__non_square.png'),
    nonSquareResize: path.resolve(process.cwd(), 'fixtures/Sheet_1-1__crop_1600x1001.png'),
  };

  const fixtureReportData: ParityReport['fixtures'] = {};

  for (const [key, fPath] of Object.entries(fixturePaths)) {
    if (!fs.existsSync(fPath)) {
      throw new Error(`Fixture file missing: ${fPath}`);
    }
    const fSha = computeFileSha256(fPath);
    const refFixture = refData.fixtures[key];
    if (!refFixture) {
      const err = new Error(`REFERENCE_CONFIG_MISMATCH: Fixture '${key}' not found in reference JSON`);
      (err as any).statusCode = 'REFERENCE_CONFIG_MISMATCH';
      throw err;
    }

    if (refFixture.sha256 !== fSha) {
      const err = new Error(
        `REFERENCE_HASH_MISMATCH: Fixture '${key}' SHA mismatch. Disk=${fSha}, Reference=${refFixture.sha256}`,
      );
      (err as any).statusCode = 'REFERENCE_HASH_MISMATCH';
      throw err;
    }

    fixtureReportData[key] = {
      path: fPath,
      dimensions: refFixture.dimensions,
      diskSha256: fSha,
      referenceSha256: refFixture.sha256,
    };
  }

  // 5. Execute Node.js Inference on all fixtures
  const session = await getYoloV203Session(modelPath);
  const decodeConfig = {
    confidenceThreshold: expectedConf,
    nmsIouThreshold: expectedIou,
    maxDetections: expectedMaxDet,
  };

  async function executeNodeInference(imgPath: string): Promise<YoloV203Detection[]> {
    const buf = fs.readFileSync(imgPath);
    const { tensor, meta } = await preprocessForYolo(buf, YOLO_V203_INPUT_SIZE);
    const flatData = tensor instanceof Float32Array ? tensor : new Float32Array(tensor);
    const inputName = session.inputNames[0] || 'images';
    const feeds: Record<string, ort.Tensor> = {
      [inputName]: new ort.Tensor('float32', flatData, [1, 3, YOLO_V203_INPUT_SIZE, YOLO_V203_INPUT_SIZE]),
    };
    const results = await session.run(feeds);
    const outputName = session.outputNames[0] || 'output0';
    const outputTensor = results[outputName];
    const outputData = outputTensor.data as Float32Array;
    return decodeAndFilterV203(outputData, meta, decodeConfig);
  }

  const comparisons: ParityComparisonRow[] = [];
  let maxConfDelta = 0;
  let maxBboxDelta = 0;
  let matchedCount = 0;
  let missingCount = 0;
  let extraCount = 0;
  let totalPythonDetections = 0;
  let totalNodeDetections = 0;

  // 6. Geometric Bipartite Matching per Fixture & Class
  for (const [key, fPath] of Object.entries(fixturePaths)) {
    const refFixture = refData.fixtures[key];
    const pyDetections = refFixture.detections;
    const nodeDetections = await executeNodeInference(fPath);

    totalPythonDetections += pyDetections.length;
    totalNodeDetections += nodeDetections.length;

    // Group by rawClassId
    const distinctClassIds = Array.from(
      new Set([
        ...pyDetections.map((p) => p.rawClassId),
        ...nodeDetections.map((n) => n.rawClassId),
      ]),
    );

    for (const classId of distinctClassIds) {
      const pyClassItems = pyDetections
        .map((p, idx) => ({ index: idx, score: p.score, bbox: p.bbox, rawClassId: p.rawClassId }))
        .filter((p) => p.rawClassId === classId);

      const nodeClassItems = nodeDetections
        .map((n, idx) => ({
          index: idx,
          score: n.confidence,
          bbox: [n.pixelBox.x1, n.pixelBox.y1, n.pixelBox.x2, n.pixelBox.y2] as [number, number, number, number],
          rawClassId: n.rawClassId,
        }))
        .filter((n) => n.rawClassId === classId);

      const matching = solveGeometricBipartiteMatching(pyClassItems, nodeClassItems);

      // Record Matched Pairs
      for (const match of matching.matchedPairs) {
        const pyDet = pyDetections[match.pyIndex];
        const nodeDet = nodeDetections[match.nodeIndex];
        const pb = nodeDet.pixelBox;

        const cDelta = Math.abs(nodeDet.confidence - pyDet.score);
        const bDeltas = [
          Math.abs(pb.x1 - pyDet.bbox[0]),
          Math.abs(pb.y1 - pyDet.bbox[1]),
          Math.abs(pb.x2 - pyDet.bbox[2]),
          Math.abs(pb.y2 - pyDet.bbox[3]),
        ];
        const maxBDelta = Math.max(...bDeltas);

        if (cDelta > maxConfDelta) maxConfDelta = cDelta;
        if (maxBDelta > maxBboxDelta) maxBboxDelta = maxBDelta;

        const withinTol = cDelta <= 1e-4 && maxBDelta <= 0.5;
        matchedCount++;

        comparisons.push({
          fixture: `${key} (${refFixture.filename})`,
          rawClassId: classId,
          pyConfidence: pyDet.score,
          nodeConfidence: nodeDet.confidence,
          confDelta: cDelta,
          pyBbox: pyDet.bbox,
          nodeBbox: [pb.x1, pb.y1, pb.x2, pb.y2],
          maxBboxDelta: maxBDelta,
          l1Distance: match.l1Distance,
          iou: match.iou,
          matched: true,
          status: withinTol ? 'MATCH' : 'MISMATCH',
        });
      }

      // Record Missing Python Detections
      for (const pIdx of matching.unmatchedPyIndices) {
        missingCount++;
        const pyDet = pyDetections[pIdx];
        comparisons.push({
          fixture: `${key} (${refFixture.filename})`,
          rawClassId: classId,
          pyConfidence: pyDet.score,
          nodeConfidence: null,
          confDelta: null,
          pyBbox: pyDet.bbox,
          nodeBbox: null,
          maxBboxDelta: null,
          l1Distance: null,
          iou: null,
          matched: false,
          status: 'MISSING',
        });
      }

      // Record Extra Node Detections
      for (const nIdx of matching.unmatchedNodeIndices) {
        extraCount++;
        const nodeDet = nodeDetections[nIdx];
        const pb = nodeDet.pixelBox;
        comparisons.push({
          fixture: `${key} (${refFixture.filename})`,
          rawClassId: classId,
          pyConfidence: null,
          nodeConfidence: nodeDet.confidence,
          confDelta: null,
          pyBbox: null,
          nodeBbox: [pb.x1, pb.y1, pb.x2, pb.y2],
          maxBboxDelta: null,
          l1Distance: null,
          iou: null,
          matched: false,
          status: 'EXTRA',
        });
      }
    }
  }

  const passed =
    missingCount === 0 &&
    extraCount === 0 &&
    maxConfDelta <= 1e-4 &&
    maxBboxDelta <= 0.5;

  const statusCode = passed ? 'PARITY_PASSED' : 'PARITY_MISMATCH';

  return {
    statusCode,
    referenceMetadata: refData.metadata,
    model: {
      path: modelPath,
      diskSha256: modelDiskSha,
      referenceSha256: refData.metadata.model.sha256,
    },
    fixtures: fixtureReportData,
    config: decodeConfig,
    comparisons,
    summary: {
      totalPythonDetections,
      totalNodeDetections,
      matchedCount,
      missingCount,
      extraCount,
      maxConfDelta,
      maxBboxDelta,
      passed,
    },
  };
}

async function main() {
  const isJson = process.argv.includes('--json');

  try {
    const report = await runParityVerification();

    if (isJson) {
      process.stdout.write(JSON.stringify(report, null, 2) + '\n');
      process.exit(report.summary.passed ? 0 : 1);
    }

    console.log('🔬 YOLO v203 Cross-Runtime Parity Report (Python vs Node.js)');
    console.log('===========================================================');
    console.log(`Status               : ${report.statusCode}`);
    console.log(`Model SHA-256 (Disk) : ${report.model.diskSha256}`);
    console.log(`Model SHA (Ref)      : ${report.model.referenceSha256}`);
    console.log(`Python Runtime Env   : Python ${report.referenceMetadata?.environment.pythonVersion}, ORT ${report.referenceMetadata?.environment.onnxruntimeVersion}`);
    console.log(`Provider             : ${report.referenceMetadata?.environment.executionProvider}`);
    console.log(`Geometric Gate       : IoU > 0 OR Distance <= ${GEOMETRIC_GATE_MAX_DISTANCE}px`);
    console.log('');
    console.log('📁 FIXTURES VERIFIED:');
    for (const [k, f] of Object.entries(report.fixtures)) {
      console.log(`  - [${k}] ${f.path}`);
      console.log(`    Dims: ${f.dimensions[0]}x${f.dimensions[1]} | SHA: ${f.diskSha256}`);
    }
    console.log('');
    console.log('📊 ONE-TO-ONE DETECTION COMPARISONS');
    console.log('-----------------------------------');
    for (const c of report.comparisons) {
      console.log(`[${c.fixture}] Class ${c.rawClassId} -> Status: ${c.status}`);
      if (c.status === 'MATCH' || c.status === 'MISMATCH') {
        console.log(`  - Confidence : Python=${c.pyConfidence?.toFixed(6)} | Node=${c.nodeConfidence?.toFixed(6)} | Δ=${c.confDelta?.toExponential(4)}`);
        console.log(`  - BBox Python: [${c.pyBbox?.map((v) => v.toFixed(2)).join(', ')}]`);
        console.log(`  - BBox Node  : [${c.nodeBbox?.map((v) => v.toFixed(2)).join(', ')}]`);
        console.log(`  - Max BBox Δ : ${c.maxBboxDelta?.toFixed(4)} px (IoU: ${c.iou?.toFixed(4)}, L1 Dist: ${c.l1Distance?.toFixed(2)} px)`);
      } else if (c.status === 'MISSING') {
        console.log(`  - Python detection with score ${c.pyConfidence?.toFixed(4)} at [${c.pyBbox?.map((v) => v.toFixed(2)).join(', ')}] had no matching Node detection`);
      } else if (c.status === 'EXTRA') {
        console.log(`  - Node detection with score ${c.nodeConfidence?.toFixed(4)} at [${c.nodeBbox?.map((v) => v.toFixed(2)).join(', ')}] had no matching Python reference`);
      }
    }
    console.log('');
    console.log('📈 SUMMARY');
    console.log('----------');
    console.log(`Python Detections    : ${report.summary.totalPythonDetections}`);
    console.log(`Node.js Detections   : ${report.summary.totalNodeDetections}`);
    console.log(`Matched (1-to-1)     : ${report.summary.matchedCount}`);
    console.log(`Missing              : ${report.summary.missingCount}`);
    console.log(`Extra                : ${report.summary.extraCount}`);
    console.log(`Max Confidence Delta : ${report.summary.maxConfDelta.toExponential(4)} (threshold <= 1e-4)`);
    console.log(`Max BBox Delta       : ${report.summary.maxBboxDelta.toFixed(4)} px (threshold <= 0.5 px)`);
    console.log('===========================================================');

    if (report.summary.passed) {
      console.log('✅ CROSS-RUNTIME PARITY: PASSED (Exact match within tolerance)');
      process.exit(0);
    } else {
      console.error(`❌ CROSS-RUNTIME PARITY: FAILED (${report.statusCode})`);
      process.exit(1);
    }
  } catch (err: any) {
    const code = err.statusCode || 'PARITY_MISMATCH';
    if (isJson) {
      process.stdout.write(JSON.stringify({ statusCode: code, error: err.message }, null, 2) + '\n');
    } else {
      console.error(`❌ Parity verification error [${code}]: ${err.message}`);
    }
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}
